css:
.mtn-tab-underline{font-family:system-ui,-apple-system,"Segoe UI",sans-serif;background:radial-gradient(130% 110% at 0% 0%,#141d2c,#0b0f18 62%);border:1px solid #1e2a3d;border-radius:14px;padding:12px 14px 14px;color:#c8d6ea;}
.mtn-tab-underline-bar{position:relative;display:flex;gap:2px;border-bottom:1px solid #1c2637;}
.mtn-tab-underline-tab{appearance:none;background:none;border:0;margin:0;padding:8px 7px 10px;font:600 12.5px/1 system-ui,-apple-system,sans-serif;color:#7f8ea6;cursor:pointer;display:flex;align-items:center;gap:6px;border-radius:8px 8px 0 0;transition:color .22s ease,background .22s ease;}
.mtn-tab-underline-tab:hover{color:#dce8fa;background:rgba(120,160,255,.07);}
.mtn-tab-underline-tab:focus-visible{outline:2px solid #38e0d4;outline-offset:-2px;color:#eaf3ff;}
.mtn-tab-underline-tab[aria-selected="true"]{color:#f2f7ff;}
.mtn-tab-underline-badge{font:600 10px/1 ui-monospace,Menlo,monospace;background:#1d2a3d;color:#8fa6c4;padding:3px 5px;border-radius:20px;transition:background .24s ease,color .24s ease;}
.mtn-tab-underline-tab[aria-selected="true"] .mtn-tab-underline-badge{background:rgba(56,224,212,.16);color:#5ff0e2;}
.mtn-tab-underline-ink{position:absolute;left:0;bottom:-1px;height:2px;width:0;border-radius:2px;background:linear-gradient(90deg,#38e0d4,#7c9dff);box-shadow:0 0 10px rgba(56,224,212,.55);pointer-events:none;transition:transform .3s cubic-bezier(.32,.9,.28,1),width .3s cubic-bezier(.32,.9,.28,1);}
.mtn-tab-underline-panels{position:relative;padding-top:12px;min-height:72px;}
.mtn-tab-underline-panel{display:none;}
.mtn-tab-underline-panel[data-on="1"]{display:block;animation:mtn-tab-underline-swap .36s cubic-bezier(.22,.9,.3,1) both;}
.mtn-tab-underline-lead{margin:0 0 9px;font-size:13px;color:#e6eefb;}
.mtn-tab-underline-meter{height:5px;border-radius:5px;background:#18222f;overflow:hidden;}
.mtn-tab-underline-meter i{display:block;height:100%;border-radius:5px;background:linear-gradient(90deg,#38e0d4,#7c9dff);}
.mtn-tab-underline-meta{display:block;margin-top:9px;font:500 11px/1 ui-monospace,Menlo,monospace;color:#6d7d95;letter-spacing:.02em;}
.mtn-tab-underline-row{display:flex;justify-content:space-between;align-items:baseline;gap:10px;font-size:12px;padding:5px 0;border-bottom:1px dashed #1a2432;color:#b6c6dc;}
.mtn-tab-underline-row b{font-weight:600;color:#e9f1ff;}
.mtn-tab-underline-row span{font:500 11px/1.4 ui-monospace,Menlo,monospace;color:#6d7d95;}
@keyframes mtn-tab-underline-swap{from{opacity:0;transform:translateX(calc(var(--mtn-tu-dir,1) * 14px));}to{opacity:1;transform:none;}}
@media (prefers-reduced-motion: reduce){
  .mtn-tab-underline-ink{transition-duration:.001ms;}
  .mtn-tab-underline-panel[data-on="1"]{animation-duration:.001ms;}
}

js:
var bar = root.querySelector('.mtn-tab-underline-bar');
var tabs = Array.prototype.slice.call(root.querySelectorAll('.mtn-tab-underline-tab'));
var panels = Array.prototype.slice.call(root.querySelectorAll('.mtn-tab-underline-panel'));
var ink = root.querySelector('.mtn-tab-underline-ink');
var cur = 0, px = 0, pw = 0, timer = 0;

function place(i, animate) {
  var b = tabs[i].getBoundingClientRect(), p = bar.getBoundingClientRect();
  var x = b.left - p.left, w = b.width;
  if (!animate) {
    ink.style.transition = 'none';
    ink.style.transform = 'translateX(' + x + 'px)';
    ink.style.width = w + 'px';
    void ink.offsetWidth;
    ink.style.transition = '';
  } else {
    var l = Math.min(px, x), r = Math.max(px + pw, x + w);
    ink.style.transform = 'translateX(' + l + 'px)';
    ink.style.width = (r - l) + 'px';
    clearTimeout(timer);
    timer = setTimeout(function () {
      if (!root.isConnected) return;
      ink.style.transform = 'translateX(' + x + 'px)';
      ink.style.width = w + 'px';
    }, 150);
  }
  px = x; pw = w;
}

function select(i, focus) {
  if (i === cur) { tabs[i].focus(); return; }
  root.style.setProperty('--mtn-tu-dir', i > cur ? 1 : -1);
  tabs.forEach(function (t, n) {
    t.setAttribute('aria-selected', n === i ? 'true' : 'false');
    t.tabIndex = n === i ? 0 : -1;
  });
  panels.forEach(function (p, n) { p.setAttribute('data-on', n === i ? '1' : '0'); });
  place(i, true);
  cur = i;
  if (focus) tabs[i].focus();
}

tabs.forEach(function (t, i) {
  t.addEventListener('click', function () { select(i, false); });
});

bar.addEventListener('keydown', function (e) {
  var k = e.key, n = -1;
  if (k === 'ArrowRight') n = (cur + 1) % tabs.length;
  else if (k === 'ArrowLeft') n = (cur - 1 + tabs.length) % tabs.length;
  else if (k === 'Home') n = 0;
  else if (k === 'End') n = tabs.length - 1;
  if (n < 0) return;
  e.preventDefault();
  select(n, true);
});

requestAnimationFrame(function () {
  if (!root.isConnected) return;
  place(0, false);
});

if (typeof ResizeObserver === 'function') {
  var ro = new ResizeObserver(function () {
    if (!root.isConnected) { ro.disconnect(); return; }
    place(cur, false);
  });
  ro.observe(bar);
}

css:
.mtn-rail-morph{display:flex;gap:10px;font-family:system-ui,-apple-system,"Segoe UI",sans-serif;background:linear-gradient(155deg,#0e1511,#0a0d12 66%);border:1px solid #1c2a1f;border-radius:14px;padding:10px;color:#cfe0d3;}
.mtn-rail-morph-rail{position:relative;width:50px;flex:none;display:flex;flex-direction:column;gap:10px;transition:width .44s cubic-bezier(.2,.85,.25,1);}
.mtn-rail-morph[data-open="1"] .mtn-rail-morph-rail{width:134px;}
.mtn-rail-morph-toggle{width:32px;height:32px;flex:none;display:grid;place-items:center;background:#101a12;border:1px solid #23331f;border-radius:9px;cursor:pointer;transition:background .2s ease,border-color .2s ease;}
.mtn-rail-morph-toggle:hover{background:#152214;border-color:#3a4f2b;}
.mtn-rail-morph-toggle:focus-visible{outline:2px solid #a3e635;outline-offset:2px;}
.mtn-rail-morph-burger{position:relative;width:14px;height:2px;border-radius:2px;background:#9fb8a6;transition:background .2s ease;}
.mtn-rail-morph-burger::before,.mtn-rail-morph-burger::after{content:"";position:absolute;left:0;width:14px;height:2px;border-radius:2px;background:#9fb8a6;transform-origin:left center;transition:transform .4s cubic-bezier(.3,.9,.3,1),background .3s ease;}
.mtn-rail-morph-burger::before{transform:translateY(-5px);}
.mtn-rail-morph-burger::after{transform:translateY(5px);}
.mtn-rail-morph[data-open="1"] .mtn-rail-morph-burger{background:transparent;}
.mtn-rail-morph[data-open="1"] .mtn-rail-morph-burger::before{transform:translate(2px,-3px) rotate(-42deg) scaleX(.72);background:#a3e635;}
.mtn-rail-morph[data-open="1"] .mtn-rail-morph-burger::after{transform:translate(2px,3px) rotate(42deg) scaleX(.72);background:#a3e635;}
.mtn-rail-morph-list{position:relative;list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:4px;}
.mtn-rail-morph-cursor{position:absolute;left:0;top:0;width:100%;height:32px;border-radius:9px;background:linear-gradient(90deg,rgba(163,230,53,.2),rgba(163,230,53,.04));box-shadow:inset 0 0 0 1px rgba(163,230,53,.28);transform:translateY(calc(var(--mtn-rm-i,0) * 36px));transition:transform .46s cubic-bezier(.34,1.24,.4,1);}
.mtn-rail-morph-cursor::before{content:"";position:absolute;left:0;top:9px;width:3px;height:14px;border-radius:0 3px 3px 0;background:#a3e635;}
.mtn-rail-morph-item{position:relative;display:flex;align-items:center;gap:10px;width:100%;height:32px;padding:0 9px;background:none;border:0;border-radius:9px;color:#8ba394;font:600 12.5px/1 system-ui,-apple-system,sans-serif;text-align:left;cursor:pointer;transition:color .22s ease;}
.mtn-rail-morph-item:hover{color:#d7ead9;}
.mtn-rail-morph-item:focus-visible{outline:2px solid #a3e635;outline-offset:-2px;}
.mtn-rail-morph-item[aria-current="page"]{color:#eafbe4;}
.mtn-rail-morph-ico{width:16px;height:16px;flex:none;opacity:.9;}
.mtn-rail-morph-ico[data-g="grid"]{background:linear-gradient(currentColor,currentColor) 0 0/6px 6px no-repeat,linear-gradient(currentColor,currentColor) 10px 0/6px 6px no-repeat,linear-gradient(currentColor,currentColor) 0 10px/6px 6px no-repeat,linear-gradient(currentColor,currentColor) 10px 10px/6px 6px no-repeat;}
.mtn-rail-morph-ico[data-g="chart"]{background:linear-gradient(currentColor,currentColor) 0 100%/3px 55% no-repeat,linear-gradient(currentColor,currentColor) 6px 100%/3px 100% no-repeat,linear-gradient(currentColor,currentColor) 12px 100%/3px 32% no-repeat;}
.mtn-rail-morph-ico[data-g="flow"]{background:linear-gradient(currentColor,currentColor) 0 7px/16px 2px no-repeat,radial-gradient(circle 3px at 3px 8px,currentColor 98%,transparent) no-repeat,radial-gradient(circle 3px at 13px 8px,currentColor 98%,transparent) no-repeat;}
.mtn-rail-morph-ico[data-g="people"]{background:radial-gradient(circle 4px at 5px 5px,currentColor 98%,transparent) no-repeat,radial-gradient(circle 4px at 12px 8px,currentColor 98%,transparent) no-repeat,linear-gradient(currentColor,currentColor) 0 14px/16px 2px no-repeat;}
.mtn-rail-morph-label{white-space:nowrap;}
.mtn-rail-morph[data-open="1"] .mtn-rail-morph-label{animation:mtn-rail-morph-slidein .38s cubic-bezier(.2,.9,.3,1) backwards;animation-delay:calc(var(--mtn-rm-d,0) * 45ms);}
.mtn-rail-morph[data-open="0"] .mtn-rail-morph-label{position:absolute;left:calc(100% + 8px);top:50%;transform:translate(-6px,-50%);opacity:0;pointer-events:none;background:#0f1a13;border:1px solid #26381f;color:#dcefdd;padding:4px 8px;border-radius:7px;font-size:11.5px;z-index:5;transition:opacity .18s ease,transform .26s cubic-bezier(.2,.9,.3,1);}
.mtn-rail-morph[data-open="0"] .mtn-rail-morph-item:hover .mtn-rail-morph-label{opacity:1;transform:translate(0,-50%);}
.mtn-rail-morph[data-open="0"] .mtn-rail-morph-item:focus-visible .mtn-rail-morph-label{opacity:1;transform:translate(0,-50%);}
.mtn-rail-morph-stage{flex:1;min-width:0;border-left:1px solid #18261a;padding-left:12px;display:flex;flex-direction:column;justify-content:center;}
.mtn-rail-morph-kick{font:600 9.5px/1 ui-monospace,Menlo,monospace;letter-spacing:.18em;text-transform:uppercase;color:#5d7a63;}
.mtn-rail-morph-title{margin:6px 0 5px;font-size:16px;font-weight:650;color:#edfaea;animation:mtn-rail-morph-rise .4s cubic-bezier(.2,.9,.3,1) both;}
.mtn-rail-morph-sub{margin:0;font-size:11.5px;line-height:1.45;color:#84a08b;animation:mtn-rail-morph-rise .4s cubic-bezier(.2,.9,.3,1) .05s both;}
@keyframes mtn-rail-morph-slidein{from{opacity:0;transform:translateX(-10px);}to{opacity:1;transform:none;}}
@keyframes mtn-rail-morph-rise{from{opacity:0;transform:translateY(7px);}to{opacity:1;transform:none;}}
@media (prefers-reduced-motion: reduce){
  .mtn-rail-morph-rail{transition-duration:.001ms;}
  .mtn-rail-morph-cursor{transition-duration:.001ms;}
  .mtn-rail-morph-title{animation:none;}
  .mtn-rail-morph-sub{animation:none;}
  .mtn-rail-morph[data-open="1"] .mtn-rail-morph-label{animation:none;}
}

js:
var toggle = root.querySelector('.mtn-rail-morph-toggle');
var items = Array.prototype.slice.call(root.querySelectorAll('.mtn-rail-morph-item'));
var title = root.querySelector('.mtn-rail-morph-title');
var sub = root.querySelector('.mtn-rail-morph-sub');
var cur = 0;

toggle.addEventListener('click', function () {
  var open = root.getAttribute('data-open') === '1' ? '0' : '1';
  root.setAttribute('data-open', open);
  toggle.setAttribute('aria-expanded', open === '1' ? 'true' : 'false');
  toggle.setAttribute('aria-label', open === '1' ? 'Collapse navigation' : 'Expand navigation');
});

function replay(el) {
  el.style.animation = 'none';
  void el.offsetWidth;
  el.style.animation = '';
}

function pick(i) {
  cur = i;
  root.style.setProperty('--mtn-rm-i', i);
  items.forEach(function (b, n) {
    if (n === i) b.setAttribute('aria-current', 'page');
    else b.removeAttribute('aria-current');
  });
  title.textContent = items[i].getAttribute('data-title');
  sub.textContent = items[i].getAttribute('data-sub');
  replay(title);
  replay(sub);
}

items.forEach(function (b, i) {
  b.addEventListener('click', function () { pick(i); });
  b.addEventListener('keydown', function (e) {
    var n = -1;
    if (e.key === 'ArrowDown') n = (i + 1) % items.length;
    else if (e.key === 'ArrowUp') n = (i - 1 + items.length) % items.length;
    if (n < 0) return;
    e.preventDefault();
    items[n].focus();
  });
});

root.style.setProperty('--mtn-rm-i', 0);

css:
.mtn-dock-magnify{font-family:system-ui,-apple-system,"Segoe UI",sans-serif;background:linear-gradient(180deg,#1a1d29,#0b0d14 70%);border:1px solid #262b3b;border-radius:16px;padding:12px 10px 10px;color:#dfe4f2;}
.mtn-dock-magnify-screen{display:flex;align-items:baseline;gap:8px;padding:0 4px 10px;}
.mtn-dock-magnify-kick{font:600 9.5px/1 ui-monospace,Menlo,monospace;letter-spacing:.16em;text-transform:uppercase;color:#6f7690;}
.mtn-dock-magnify-app{font-size:13.5px;font-weight:650;color:#fff;animation:mtn-dock-magnify-pop .34s cubic-bezier(.2,.9,.3,1) both;}
.mtn-dock-magnify-dock{position:relative;display:flex;align-items:flex-end;justify-content:center;gap:9px;padding:8px 10px 7px;border-radius:16px;background:linear-gradient(180deg,rgba(255,255,255,.09),rgba(255,255,255,.03));border:1px solid rgba(255,255,255,.09);box-shadow:0 10px 26px rgba(0,0,0,.45),inset 0 1px 0 rgba(255,255,255,.12);}
.mtn-dock-magnify-item{position:relative;width:28px;padding:0;margin:0;background:none;border:0;cursor:pointer;display:flex;flex-direction:column;align-items:center;}
.mtn-dock-magnify-item:focus-visible{outline:none;}
.mtn-dock-magnify-tile{width:28px;height:28px;border-radius:8px;transform-origin:bottom center;transform:translateY(calc((var(--mtn-dm-s,1) - 1) * -7px)) scale(var(--mtn-dm-s,1));transition:transform .13s cubic-bezier(.3,.8,.4,1),box-shadow .2s ease;box-shadow:0 2px 6px rgba(0,0,0,.4),inset 0 1px 0 rgba(255,255,255,.28);position:relative;}
.mtn-dock-magnify-item:focus-visible .mtn-dock-magnify-tile{box-shadow:0 0 0 2px #0b0d14,0 0 0 4px #7dd3fc;}
.mtn-dock-magnify-tile[data-t="finder"]{background:linear-gradient(160deg,#5ec2ff,#1f6fd0);}
.mtn-dock-magnify-tile[data-t="mail"]{background:linear-gradient(160deg,#7fd8ff,#2f8bf0);}
.mtn-dock-magnify-tile[data-t="notes"]{background:linear-gradient(160deg,#ffd977,#e8a71f);}
.mtn-dock-magnify-tile[data-t="music"]{background:linear-gradient(160deg,#ff7a9c,#e0245e);}
.mtn-dock-magnify-tile[data-t="photos"]{background:linear-gradient(160deg,#b892ff,#6b3fd4);}
.mtn-dock-magnify-tile[data-t="trash"]{background:linear-gradient(160deg,#9aa6bd,#5a6577);}
.mtn-dock-magnify-tile::after{content:"";position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);}
.mtn-dock-magnify-tile[data-t="finder"]::after{width:13px;height:13px;border:1.6px solid rgba(255,255,255,.95);border-radius:3px;box-shadow:inset 5.5px 0 0 -4.6px rgba(255,255,255,.95);}
.mtn-dock-magnify-tile[data-t="mail"]::after{width:15px;height:10px;border:1.6px solid rgba(255,255,255,.95);border-radius:2px;}
.mtn-dock-magnify-tile[data-t="mail"]::before{content:"";position:absolute;left:50%;top:44%;width:7px;height:7px;border-right:1.6px solid rgba(255,255,255,.95);border-bottom:1.6px solid rgba(255,255,255,.95);transform:translate(-50%,-70%) rotate(45deg);z-index:1;}
.mtn-dock-magnify-tile[data-t="notes"]::after{width:13px;height:11px;background:linear-gradient(rgba(255,255,255,.95),rgba(255,255,255,.95)) 0 0/13px 1.8px no-repeat,linear-gradient(rgba(255,255,255,.95),rgba(255,255,255,.95)) 0 4.6px/13px 1.8px no-repeat,linear-gradient(rgba(255,255,255,.95),rgba(255,255,255,.95)) 0 9.2px/8px 1.8px no-repeat;}
.mtn-dock-magnify-tile[data-t="music"]::after{width:12px;height:12px;background:radial-gradient(circle 3.6px at 3.6px 9px,rgba(255,255,255,.95) 98%,transparent) no-repeat,linear-gradient(rgba(255,255,255,.95),rgba(255,255,255,.95)) 6.4px 0/1.8px 9px no-repeat;}
.mtn-dock-magnify-tile[data-t="photos"]::after{width:12px;height:12px;border:1.8px solid rgba(255,255,255,.95);border-radius:50%;box-shadow:inset 0 0 0 2.4px rgba(255,255,255,.4);}
.mtn-dock-magnify-tile[data-t="trash"]::after{width:11px;height:12px;border:1.6px solid rgba(255,255,255,.95);border-top-width:0;border-radius:0 0 3px 3px;margin-top:2px;}
.mtn-dock-magnify-tile[data-t="trash"]::before{content:"";position:absolute;left:50%;top:6px;width:15px;height:1.8px;border-radius:2px;background:rgba(255,255,255,.95);transform:translateX(-50%);z-index:1;}
.mtn-dock-magnify-dot{width:3px;height:3px;margin-top:4px;border-radius:50%;background:transparent;transition:background .2s ease;}
.mtn-dock-magnify-item[data-run="1"] .mtn-dock-magnify-dot{background:rgba(255,255,255,.6);}
.mtn-dock-magnify-tip{position:absolute;bottom:calc(100% + 6px);left:50%;transform:translate(-50%,4px);opacity:0;pointer-events:none;white-space:nowrap;font:600 11px/1 system-ui,-apple-system,sans-serif;color:#0b0d14;background:#e7ecf7;padding:4px 7px;border-radius:6px;transition:opacity .16s ease,transform .22s cubic-bezier(.2,.9,.3,1);}
.mtn-dock-magnify-item:hover .mtn-dock-magnify-tip{opacity:1;transform:translate(-50%,0);}
.mtn-dock-magnify-item:focus-visible .mtn-dock-magnify-tip{opacity:1;transform:translate(-50%,0);}
.mtn-dock-magnify-item:focus-visible{--mtn-dm-s:1.34;}
@keyframes mtn-dock-magnify-pop{from{opacity:0;transform:translateY(5px);}to{opacity:1;transform:none;}}
@media (prefers-reduced-motion: reduce){
  .mtn-dock-magnify-tile{transform:none !important;transition:none;}
  .mtn-dock-magnify-app{animation:none;}
  .mtn-dock-magnify-tip{transition-duration:.001ms;}
}

js:
var dock = root.querySelector('.mtn-dock-magnify-dock');
var items = Array.prototype.slice.call(root.querySelectorAll('.mtn-dock-magnify-item'));
var label = root.querySelector('.mtn-dock-magnify-app');
var px = null, frame = 0;

function paint() {
  if (!root.isConnected) { frame = 0; return; }
  frame = 0;
  for (var i = 0; i < items.length; i++) {
    var it = items[i];
    if (px === null) { it.style.removeProperty('--mtn-dm-s'); continue; }
    var c = it.offsetLeft + it.offsetWidth / 2;
    var d = px - c;
    var s = 1 + 0.58 * Math.exp(-(d * d) / 1900);
    it.style.setProperty('--mtn-dm-s', s.toFixed(3));
  }
}

function schedule() {
  if (!frame) frame = requestAnimationFrame(paint);
}

dock.addEventListener('pointermove', function (e) {
  var r = dock.getBoundingClientRect();
  px = e.clientX - r.left - dock.clientLeft;
  schedule();
});

dock.addEventListener('pointerleave', function () { px = null; schedule(); });

items.forEach(function (it) {
  it.addEventListener('click', function () {
    it.setAttribute('data-run', '1');
    label.textContent = it.getAttribute('data-app');
    label.style.animation = 'none';
    void label.offsetWidth;
    label.style.animation = '';
  });
});

css:
.mtn-crumb-slide{font-family:ui-monospace,Menlo,Consolas,monospace;background:linear-gradient(180deg,#0f0d0a,#08080a 70%);border:1px solid #2a2118;border-radius:12px;padding:11px 12px 12px;color:#d6c7b2;}
.mtn-crumb-slide-bar{display:flex;align-items:center;overflow:hidden;padding-bottom:9px;border-bottom:1px solid #211a13;}
.mtn-crumb-slide-track{display:flex;align-items:center;min-width:0;}
.mtn-crumb-slide-crumb{appearance:none;background:none;border:0;padding:3px 6px;margin:0;border-radius:6px;font:600 12px/1 ui-monospace,Menlo,monospace;color:#8c7a63;cursor:pointer;white-space:nowrap;transition:color .2s ease,background .2s ease;}
.mtn-crumb-slide-crumb:hover{color:#f3d9b0;background:rgba(240,162,74,.1);}
.mtn-crumb-slide-crumb:focus-visible{outline:2px solid #f0a24a;outline-offset:1px;}
.mtn-crumb-slide-seg{display:flex;align-items:center;}
.mtn-crumb-slide-sep{color:#63503a;font-size:12px;padding:0 1px;}
.mtn-crumb-slide-crumb[data-cur="1"]{color:#0d0b08;background:linear-gradient(180deg,#ffc46b,#f0a24a);box-shadow:0 2px 10px rgba(240,162,74,.28);}
.mtn-crumb-slide-seg[data-cur="1"] .mtn-crumb-slide-crumb{color:#0d0b08;background:linear-gradient(180deg,#ffc46b,#f0a24a);box-shadow:0 2px 10px rgba(240,162,74,.28);}
