js:
var TREE = {
  projects: { atlas: { src: {}, docs: {} }, ledger: { migrations: {} } },
  notes: { inbox: {}, archive: {} },
  media: {}
};
var SIZE = { projects: '3 items', notes: '2 items', media: 'empty', atlas: '2 items',
  ledger: '1 item', src: '18 files', docs: '6 files', migrations: '9 files',
  inbox: '41 files', archive: '120 files' };

var track = root.querySelector('.mtn-crumb-slide-track');
var list = root.querySelector('.mtn-crumb-slide-list');
var rootBtn = root.querySelector('.mtn-crumb-slide-crumb[data-root="1"]');
var path = [];
var timer = 0;

function nodeAt(p) {
  var n = TREE;
  for (var i = 0; i < p.length; i++) { n = n[p[i]] || {}; }
  return n;
}

function markCurrent() {
  var segs = track.querySelectorAll('.mtn-crumb-slide-seg');
  for (var i = 0; i < segs.length; i++) {
    segs[i].setAttribute('data-cur', i === segs.length - 1 ? '1' : '0');
  }
  rootBtn.setAttribute('data-cur', segs.length ? '0' : '1');
}

function renderList() {
  var kids = Object.keys(nodeAt(path));
  list.textContent = '';
  if (!kids.length) {
    var e = document.createElement('li');
    e.className = 'mtn-crumb-slide-empty';
    e.textContent = 'no subfolders here';
    list.appendChild(e);
    return;
  }
  kids.forEach(function (name, i) {
    var li = document.createElement('li');
    var b = document.createElement('button');
    b.type = 'button';
    b.className = 'mtn-crumb-slide-row';
    b.style.animationDelay = (i * 55) + 'ms';
    var ic = document.createElement('i');
    var nm = document.createElement('b');
    nm.textContent = name;
    var sz = document.createElement('s');
    sz.textContent = SIZE[name] || '';
    b.appendChild(ic); b.appendChild(nm); b.appendChild(sz);
    b.addEventListener('click', function () { push(name); });
    li.appendChild(b);
    list.appendChild(li);
  });
}

function push(name) {
  var idx = path.length;
  path.push(name);
  var seg = document.createElement('span');
  seg.className = 'mtn-crumb-slide-seg mtn-crumb-slide-enter';
  var sep = document.createElement('span');
  sep.className = 'mtn-crumb-slide-sep';
  sep.textContent = '/';
  var b = document.createElement('button');
  b.type = 'button';
  b.className = 'mtn-crumb-slide-crumb';
  b.textContent = name;
  b.addEventListener('click', function () { popTo(idx + 1); });
  seg.appendChild(sep);
  seg.appendChild(b);
  track.appendChild(seg);
  markCurrent();
  renderList();
}

function popTo(len) {
  if (len >= path.length) return;
  path.length = len;
  var segs = Array.prototype.slice.call(track.querySelectorAll('.mtn-crumb-slide-seg'));
  var doomed = segs.slice(len);
  doomed.forEach(function (s, i) {
    s.classList.remove('mtn-crumb-slide-enter');
    s.classList.add('mtn-crumb-slide-exit');
    s.style.animationDelay = ((doomed.length - 1 - i) * 45) + 'ms';
  });
  clearTimeout(timer);
  timer = setTimeout(function () {
    if (!root.isConnected) return;
    doomed.forEach(function (s) { if (s.parentNode) s.parentNode.removeChild(s); });
    markCurrent();
  }, 200 + doomed.length * 45);
  renderList();
}

rootBtn.addEventListener('click', function () { popTo(0); });
markCurrent();
renderList();

