var canvas = root.querySelector('.mtn-radial-dial-canvas');
var fab = root.querySelector('.mtn-radial-dial-fab');
var scrim = root.querySelector('.mtn-radial-dial-scrim');
var cap = root.querySelector('.mtn-radial-dial-cap');
var out = root.querySelector('.mtn-radial-dial-out b');
var acts = Array.prototype.slice.call(root.querySelectorAll('.mtn-radial-dial-act'));
var IDLE = 'Open the dial to file something';

function setOpen(on) {
  canvas.setAttribute('data-open', on ? '1' : '0');
  fab.setAttribute('aria-expanded', on ? 'true' : 'false');
  fab.setAttribute('aria-label', on ? 'Close capture dial' : 'Open capture dial');
  acts.forEach(function (a) { a.tabIndex = on ? 0 : -1; });
  cap.textContent = on ? 'Pick a capture type' : IDLE;
  if (on) setTimeout(function () {
    if (root.isConnected && canvas.getAttribute('data-open') === '1') acts[0].focus();
  }, 60);
  else fab.focus();
}

fab.addEventListener('click', function () {
  setOpen(canvas.getAttribute('data-open') !== '1');
});

scrim.addEventListener('click', function () {
  if (canvas.getAttribute('data-open') === '1') setOpen(false);
});

acts.forEach(function (a, i) {
  a.addEventListener('click', function () {
    out.textContent = a.getAttribute('data-name');
    setOpen(false);
  });
  a.addEventListener('mouseenter', function () { cap.textContent = a.getAttribute('data-name'); });
  a.addEventListener('focus', function () { cap.textContent = a.getAttribute('data-name'); });
  a.addEventListener('mouseleave', function () {
    if (canvas.getAttribute('data-open') === '1') cap.textContent = 'Pick a capture type';
  });
  a.addEventListener('keydown', function (e) {
    var n = -1;
    if (e.key === 'ArrowUp' || e.key === 'ArrowRight') n = (i + 1) % acts.length;
    else if (e.key === 'ArrowDown' || e.key === 'ArrowLeft') n = (i - 1 + acts.length) % acts.length;
    if (n < 0) return;
    e.preventDefault();
    acts[n].focus();
  });
});

root.addEventListener('keydown', function (e) {
  if (e.key === 'Escape' && canvas.getAttribute('data-open') === '1') {
    e.preventDefault();
    setOpen(false);
  }
});

