}

js:
var ROUTES = [
  { num: '01', title: 'Journal', body: 'Field notes from the bench, posted every other Friday.', meta: '24 entries · since 2021' },
  { num: '02', title: 'Gallery', body: 'Prints, plates and process shots at full bleed.', meta: '112 frames · 6 series' },
  { num: '03', title: 'Studio', body: 'Two people, one press and a long list of offcuts.', meta: 'Leeds · open Thursdays' }
];

var links = Array.prototype.slice.call(root.querySelectorAll('.mtn-curtain-route-link'));
var curtain = root.querySelector('.mtn-curtain-route-curtain');
var num = root.querySelector('.mtn-curtain-route-num');
var title = root.querySelector('.mtn-curtain-route-title');
var body = root.querySelector('.mtn-curtain-route-body');
var meta = root.querySelector('.mtn-curtain-route-meta');
var cur = 0, busy = false, t1 = 0, t2 = 0;

function lock(on) {
  busy = on;
  links.forEach(function (l) { l.disabled = on; });
}

function swap(i) {
  var r = ROUTES[i];
  num.textContent = r.num;
  title.textContent = r.title;
  body.textContent = r.body;
  meta.textContent = r.meta;
  [num, title, body, meta].forEach(function (el) {
    el.style.animation = 'none';
    void el.offsetWidth;
    el.style.animation = '';
  });
  links.forEach(function (l, n) {
    if (n === i) l.setAttribute('aria-current', 'page');
    else l.removeAttribute('aria-current');
  });
}

function go(i) {
  if (busy || i === cur) return;
  lock(true);
  curtain.setAttribute('data-phase', 'cover');
  clearTimeout(t1); clearTimeout(t2);
  t1 = setTimeout(function () {
    if (!root.isConnected) return;
    swap(i);
    cur = i;
    curtain.setAttribute('data-phase', 'clear');
  }, 560);
  t2 = setTimeout(function () {
    if (!root.isConnected) return;
    curtain.setAttribute('data-phase', 'idle');
    lock(false);
    links[i].focus();
  }, 1120);
}

links.forEach(function (l, i) {
  l.addEventListener('click', function () { go(i); });
});

