var DATA = [
  { val: '$4,820', delta: '+6.4%', dir: 'up', bars: [22, 38, 30, 52, 44, 61, 48, 70, 58, 82, 66, 91] },
  { val: '$31,904', delta: '+2.1%', dir: 'up', bars: [60, 44, 71, 52, 84, 62, 40, 55, 78, 66, 90, 74] },
  { val: '$128,470', delta: '-3.8%', dir: 'down', bars: [88, 74, 92, 66, 58, 71, 49, 62, 44, 55, 38, 46] },
  { val: '$1.42M', delta: '+11.6%', dir: 'up', bars: [30, 42, 38, 55, 62, 58, 74, 68, 85, 79, 94, 88] }
];

var segs = Array.prototype.slice.call(root.querySelectorAll('.mtn-segment-slide-seg'));
var thumb = root.querySelector('.mtn-segment-slide-thumb');
var val = root.querySelector('.mtn-segment-slide-val');
var delta = root.querySelector('.mtn-segment-slide-delta');
var bars = Array.prototype.slice.call(root.querySelectorAll('.mtn-segment-slide-bars span'));
var cur = 0, squash = 0;

function paint(i) {
  var d = DATA[i];
  val.textContent = d.val;
  delta.textContent = d.delta;
  delta.setAttribute('data-dir', d.dir);
  [val, delta].forEach(function (el) {
    el.style.animation = 'none';
    void el.offsetWidth;
    el.style.animation = '';
  });
  bars.forEach(function (b, n) { b.style.height = d.bars[n] + '%'; });
}

function select(i, focus) {
  if (segs[i].disabled || i === cur) { if (focus) segs[i].focus(); return; }
  root.style.setProperty('--mtn-ss-i', i);
  root.style.setProperty('--mtn-ss-x', 1 + Math.min(Math.abs(i - cur), 3) * 0.06);
  clearTimeout(squash);
  squash = setTimeout(function () {
    if (!root.isConnected) return;
    root.style.setProperty('--mtn-ss-x', 1);
  }, 190);
  segs.forEach(function (s, n) {
    s.setAttribute('aria-checked', n === i ? 'true' : 'false');
    s.tabIndex = n === i ? 0 : -1;
  });
  cur = i;
  paint(i);
  if (focus) segs[i].focus();
}

segs.forEach(function (s, i) {
  s.addEventListener('click', function () { select(i, false); });
  s.addEventListener('keydown', function (e) {
    var n = i;
    if (e.key === 'ArrowRight' || e.key === 'ArrowDown') n = i + 1;
    else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') n = i - 1;
    else return;
    e.preventDefault();
    while (n >= 0 && n < segs.length && segs[n].disabled) n += (n > i ? 1 : -1);
    if (n < 0 || n >= segs.length) return;
    select(n, true);
  });
});

root.style.setProperty('--mtn-ss-i', 0);
paint(0);

