js:
var CMDS = [
  { name: 'Open project…', key: '⌘O' },
  { name: 'Toggle theme', key: '⌘J' },
  { name: 'Invite teammate', key: '⌘I' },
  { name: 'Export CSV', key: '⌘E' },
  { name: 'Keyboard shortcuts', key: '?' },
  { name: 'Duplicate page', key: '⌘D' },
  { name: 'Archive workspace', key: '' }
];

var btn = root.querySelector('.mtn-search-expand-btn');
var field = root.querySelector('.mtn-search-expand-field');
var input = root.querySelector('.mtn-search-expand-input');
var clear = root.querySelector('.mtn-search-expand-clear');
var list = root.querySelector('.mtn-search-expand-list');
var foot = root.querySelector('.mtn-search-expand-foot b');
var rows = [];
var hl = 0;

function highlight(text, q) {
  var frag = document.createDocumentFragment();
  var at = q ? text.toLowerCase().indexOf(q.toLowerCase()) : -1;
  if (at < 0) { frag.appendChild(document.createTextNode(text)); return frag; }
  frag.appendChild(document.createTextNode(text.slice(0, at)));
  var m = document.createElement('mark');
  m.textContent = text.slice(at, at + q.length);
  frag.appendChild(m);
  frag.appendChild(document.createTextNode(text.slice(at + q.length)));
  return frag;
}

function render() {
  var q = input.value.trim();
  var hits = CMDS.filter(function (c) {
    return !q || c.name.toLowerCase().indexOf(q.toLowerCase()) > -1;
  }).slice(0, 5);
  list.textContent = '';
  rows = [];
  if (!hits.length) {
    var li = document.createElement('li');
    li.className = 'mtn-search-expand-none';
    li.textContent = 'No command matches “' + q + '”';
    list.appendChild(li);
    return;
  }
  hits.forEach(function (c, i) {
    var li = document.createElement('li');
    var b = document.createElement('button');
    b.type = 'button';
    b.className = 'mtn-search-expand-row';
    b.setAttribute('role', 'option');
    b.style.animationDelay = (i * 40) + 'ms';
    b.appendChild(document.createElement('i'));
    var span = document.createElement('span');
    span.appendChild(highlight(c.name, q));
    b.appendChild(span);
    var s = document.createElement('s');
    s.textContent = c.key;
    b.appendChild(s);
    b.addEventListener('click', function () { run(c.name); });
    li.appendChild(b);
    list.appendChild(li);
    rows.push(b);
  });
  hl = 0;
  mark();
}

function mark() {
  rows.forEach(function (r, i) {
    r.setAttribute('data-hl', i === hl ? '1' : '0');
    r.setAttribute('aria-selected', i === hl ? 'true' : 'false');
  });
}

function open(on) {
  root.setAttribute('data-open', on ? '1' : '0');
  btn.setAttribute('aria-expanded', on ? 'true' : 'false');
  input.tabIndex = on ? 0 : -1;
  clear.tabIndex = on ? 0 : -1;
  if (on) { render(); input.focus(); }
  else { input.value = ''; btn.focus(); }
}

function run(name) {
  foot.textContent = name;
  open(false);
}

btn.addEventListener('click', function () {
  open(root.getAttribute('data-open') !== '1');
});

clear.addEventListener('click', function () {
  input.value = '';
  render();
  input.focus();
});

input.addEventListener('input', render);

input.addEventListener('keydown', function (e) {
  if (e.key === 'ArrowDown') { e.preventDefault(); if (rows.length) { hl = (hl + 1) % rows.length; mark(); } }
  else if (e.key === 'ArrowUp') { e.preventDefault(); if (rows.length) { hl = (hl - 1 + rows.length) % rows.length; mark(); } }
  else if (e.key === 'Enter') { e.preventDefault(); if (rows[hl]) rows[hl].click(); }
  else if (e.key === 'Escape') { e.preventDefault(); open(false); }
});

root.addEventListener('keydown', function (e) {
  if (e.key === '/' && e.target !== input && root.getAttribute('data-open') !== '1') {
    e.preventDefault();
    open(true);
  }
});

