.mtn-ink-underline{font-family:system-ui,-apple-system,"Segoe UI",sans-serif;background:linear-gradient(180deg,#131c2c,#0a0f18 62%);border:1px solid #1e2a3f;border-radius:14px;color:#c8d3e6;overflow:hidden;}
.mtn-ink-underline-bar{position:relative;display:flex;gap:0;padding:9px 7px 0;border-bottom:1px solid #1c2739;}
.mtn-ink-underline-tab{position:relative;display:inline-flex;align-items:center;gap:5px;appearance:none;background:none;border:0;margin:0;padding:7px 6px 10px;font:600 11px/1 system-ui,-apple-system,sans-serif;color:#76839b;cursor:pointer;border-radius:7px 7px 0 0;transition:color .24s ease,background-color .24s ease;}
.mtn-ink-underline-tab:hover:not(:disabled){color:#dce6f7;background:rgba(99,130,255,.08);}
.mtn-ink-underline-tab:focus-visible{outline:2px solid #60a5fa;outline-offset:-2px;}
