.mtn-ink-underline-lead{margin:6px 0 0;font:400 11.5px/1.55 system-ui,-apple-system,sans-serif;color:#8492aa;animation:mtn-ink-underline-rise .38s cubic-bezier(.2,.9,.3,1) .05s both;}
.mtn-ink-underline-chips{display:flex;flex-wrap:wrap;gap:5px;margin-top:10px;min-height:20px;}
