@keyframes mtn-ink-underline-rise{from{opacity:0;transform:translateY(7px);}to{opacity:1;transform:none;}}
@media (prefers-reduced-motion: reduce){
  .mtn-ink-underline-ink{transition-duration:.001ms;}
  .mtn-ink-underline-trail{transition-duration:.001ms;transition-delay:0ms;}
  .mtn-ink-underline-title{animation:none;}
  .mtn-ink-underline-lead{animation:none;}
  .mtn-ink-underline-chip{animation:none;}
}

js:
var DATA = [
  { title: 'trading-core', lead: 'Low-latency execution engine. Four services across two environments.', chips: ['main', 'v4.2.0', 'MIT'] },
  { title: '12 open issues', lead: 'Four are blocked on the pricing service rollout.', chips: ['3 bugs', '7 tasks', '2 chores'] },
  { title: '9 collaborators', lead: 'Access is inherited from the Platform team directory.', chips: ['4 admins', '5 write'] },
  { title: 'Plan', lead: 'Only workspace owners can change the plan.', chips: ['locked'] }
];

var tabs = Array.prototype.slice.call(root.querySelectorAll('.mtn-ink-underline-tab'));
var ink = root.querySelector('.mtn-ink-underline-ink');
var trail = root.querySelector('.mtn-ink-underline-trail');
var title = root.querySelector('.mtn-ink-underline-title');
var lead = root.querySelector('.mtn-ink-underline-lead');
var chips = root.querySelector('.mtn-ink-underline-chips');
var cur = 0;

function moveInk(el) {
  var x = el.offsetLeft + 5, w = Math.max(12, el.offsetWidth - 10);
  [ink, trail].forEach(function (n) {
    n.style.setProperty('--mtn-iu-x', x + 'px');
    n.style.setProperty('--mtn-iu-w', w + 'px');
  });
}

function replay(el) {
  el.style.animation = 'none';
  void el.offsetWidth;
  el.style.animation = '';
}

function paint(i) {
  var d = DATA[i];
  title.textContent = d.title;
  lead.textContent = d.lead;
  replay(title);
  replay(lead);
  chips.textContent = '';
  d.chips.forEach(function (t, n) {
    var s = document.createElement('span');
    s.className = 'mtn-ink-underline-chip';
    s.style.setProperty('--mtn-iu-d', n);
    s.textContent = t;
    chips.appendChild(s);
  });
}

function select(i, focus) {
  if (tabs[i].disabled || i === cur) { if (focus) tabs[i].focus(); return; }
  tabs.forEach(function (t, n) {
    t.setAttribute('aria-selected', n === i ? 'true' : 'false');
    t.tabIndex = n === i ? 0 : -1;
  });
  cur = i;
  moveInk(tabs[i]);
  paint(i);
  if (focus) tabs[i].focus();
}

tabs.forEach(function (t, i) {
  t.addEventListener('click', function () { select(i, false); });
  t.addEventListener('keydown', function (e) {
    var n = i;
    if (e.key === 'ArrowRight') n = i + 1;
    else if (e.key === 'ArrowLeft') n = i - 1;
    else if (e.key === 'Home') n = 0;
    else if (e.key === 'End') n = tabs.length - 1;
    else return;
    e.preventDefault();
    while (n >= 0 && n < tabs.length && tabs[n].disabled) n += (n >= i ? 1 : -1);
    if (n < 0 || n >= tabs.length) return;
    select(n, true);
  });
});

paint(0);
moveInk(tabs[0]);
requestAnimationFrame(function () {
  if (!root.isConnected) return;
  moveInk(tabs[cur]);
});

