var wrap = root;
var toggle = root.querySelector('.mtn-rail-flyout-toggle');
var items = Array.prototype.slice.call(root.querySelectorAll('.mtn-rail-flyout-item'));
var marker = root.querySelector('.mtn-rail-flyout-marker');
var head = root.querySelector('.mtn-rail-flyout-h');
var sub = root.querySelector('.mtn-rail-flyout-sub');
var rows = Array.prototype.slice.call(root.querySelectorAll('.mtn-rail-flyout-rows span'));
var cur = 0;

function replay(el) {
  el.style.animation = 'none';
  void el.offsetWidth;
  el.style.animation = '';
}

function place(i) {
  marker.style.setProperty('--mtn-rf-y', items[i].offsetTop + 'px');
}

function select(i) {
  cur = i;
  items.forEach(function (it, n) {
    if (n === i) it.setAttribute('aria-current', 'page');
    else it.removeAttribute('aria-current');
  });
  place(i);
  head.textContent = items[i].getAttribute('data-title');
  sub.textContent = items[i].getAttribute('data-sub');
  replay(head);
  replay(sub);
  rows.forEach(replay);
}

function setOpen(open) {
  wrap.setAttribute('data-open', open ? 'true' : 'false');
  toggle.setAttribute('aria-expanded', open ? 'true' : 'false');
  toggle.setAttribute('aria-label', open ? 'Collapse navigation' : 'Expand navigation');
}

toggle.addEventListener('click', function () {
  setOpen(wrap.getAttribute('data-open') !== 'true');
});

items.forEach(function (it, i) {
  it.addEventListener('click', function () { select(i); });
  it.addEventListener('keydown', function (e) {
    var n = i;
    if (e.key === 'ArrowDown') n = (i + 1) % items.length;
    else if (e.key === 'ArrowUp') n = (i - 1 + items.length) % items.length;
    else return;
    e.preventDefault();
    items[n].focus();
    select(n);
  });
});

place(0);
requestAnimationFrame(function () {
  if (!root.isConnected) return;
  place(cur);
});

