var dock = root.querySelector('.mtn-dock-arc-dock');
var items = Array.prototype.slice.call(root.querySelectorAll('.mtn-dock-arc-item'));
var swatch = root.querySelector('.mtn-dock-arc-swatch');
var appName = root.querySelector('.mtn-dock-arc-app');
var state = root.querySelector('.mtn-dock-arc-state');
var centers = [];
var frame = 0, px = null, bumpTimer = 0;

function measure() {
  var base = dock.getBoundingClientRect().left;
  centers = items.map(function (it) {
    var r = it.getBoundingClientRect();
    return r.left - base + r.width / 2;
  });
}

function apply() {
  var left = dock.getBoundingClientRect().left;
  items.forEach(function (it, i) {
    var m = 0;
    if (px !== null && centers[i] !== undefined) {
      var d = (px - left) - centers[i];
      m = Math.exp(-(d * d) / 1500);
      if (m < 0.02) m = 0;
    }
    it.style.setProperty('--mtn-da-m', m.toFixed(3));
  });
}

function schedule() {
  if (frame) return;
  frame = requestAnimationFrame(function () {
    if (!root.isConnected) return;
    frame = 0;
    apply();
  });
}

dock.addEventListener('pointermove', function (e) { px = e.clientX; schedule(); });
dock.addEventListener('pointerleave', function () { px = null; schedule(); });

function launch(it) {
  swatch.style.setProperty('--mtn-da-h', it.style.getPropertyValue('--mtn-da-h') || '212');
  appName.textContent = it.getAttribute('data-app');
  state.textContent = it.getAttribute('data-state');
  [appName, state].forEach(function (el) {
    el.style.animation = 'none';
    void el.offsetWidth;
    el.style.animation = '';
  });
  it.setAttribute('data-run', '1');
  it.setAttribute('data-bump', '1');
  clearTimeout(bumpTimer);
  bumpTimer = setTimeout(function () {
    if (!root.isConnected) return;
    it.removeAttribute('data-bump');
  }, 520);
}

items.forEach(function (it, i) {
  it.addEventListener('click', function () { launch(it); });
  it.addEventListener('focus', function () {
    items.forEach(function (o, n) { o.style.setProperty('--mtn-da-m', n === i ? 1 : (Math.abs(n - i) === 1 ? 0.35 : 0)); });
  });
  it.addEventListener('blur', function () {
    items.forEach(function (o) { o.style.setProperty('--mtn-da-m', 0); });
  });
});

requestAnimationFrame(function () {
  if (!root.isConnected) return;
  measure();
});

