js:
var TREE = {
  name: 'home',
  kids: [
    { name: 'projects', kids: [
      { name: 'q3-launch', kids: [
        { name: 'assets', kids: [
          { name: 'hero-2x.png', size: '1.4 MB' },
          { name: 'grid.svg', size: '22 KB' },
          { name: 'type.woff2', size: '88 KB' }
        ] },
        { name: 'brief.md', size: '6 KB' },
        { name: 'budget.csv', size: '14 KB' }
      ] },
      { name: 'atlas', kids: [ { name: 'readme.md', size: '2 KB' } ] }
    ] },
    { name: 'invoices', kids: [
      { name: '2026-07.pdf', size: '210 KB' },
      { name: '2026-08.pdf', size: '198 KB' }
    ] },
    { name: 'notes.txt', size: '3 KB' }
  ]
};

var FOLDER = '<svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linejoin="round"><path d="M2 12.4V4.2h4l1.3 1.6H14v6.6a.8.8 0 0 1-.8.8H2.8a.8.8 0 0 1-.8-.8z"/></svg>';
var FILE = '<svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linejoin="round"><path d="M4 2.6h5L12 6v7.4H4z"/><path d="M9 2.6V6h3"/></svg>';

var trail = root.querySelector('.mtn-crumb-collapse-trail');
var list = root.querySelector('.mtn-crumb-collapse-list');
var up = root.querySelector('.mtn-crumb-collapse-up');
var path = [TREE];
var expanded = false;
var timer = 0;

function sep() {
  var s = document.createElement('span');
  s.className = 'mtn-crumb-collapse-sep';
  s.textContent = '/';
  return s;
}

function crumb(i, anim, delay) {
  var b = document.createElement('button');
  b.type = 'button';
  b.className = 'mtn-crumb-collapse-crumb';
  b.textContent = path[i].name;
  b.mtnIndex = i;
  if (i === path.length - 1) b.setAttribute('aria-current', 'page');
  if (anim) { b.setAttribute('data-anim', 'in'); b.style.setProperty('--mtn-cc-d', delay || 0); }
  b.addEventListener('click', function () { if (i < path.length - 1) pop(i); });
  return b;
}

function more(hidden) {
  var m = document.createElement('button');
  m.type = 'button';
  m.className = 'mtn-crumb-collapse-more';
  m.textContent = '...';
  m.setAttribute('aria-label', 'Show ' + hidden + ' hidden folders');
  m.addEventListener('click', function () { expanded = true; drawTrail(false); });
  return m;
}

function renderTrail(hide, animLast) {
  trail.textContent = '';
  var idx = [0], i;
  if (hide > 0) idx.push(-1);
  for (i = 1 + hide; i < path.length; i++) idx.push(i);
  idx.forEach(function (n, k) {
    if (k) trail.appendChild(sep());
    if (n === -1) trail.appendChild(more(hide));
    else trail.appendChild(crumb(n, expanded || (animLast && n === path.length - 1), expanded ? k : 0));
  });
}

function fits() {
  var kids = trail.children, w = 0, i;
  for (i = 0; i < kids.length; i++) w += kids[i].offsetWidth;
  w += Math.max(0, kids.length - 1);
  return w <= trail.clientWidth;
}

function drawTrail(animLast) {
  var hide = 0;
  renderTrail(0, animLast);
  if (expanded) {
    trail.scrollLeft = trail.scrollWidth;
  } else {
    while (!fits() && hide < path.length - 2) {
      hide++;
      renderTrail(hide, animLast);
    }
  }
  up.disabled = path.length < 2;
}

function drawList() {
  list.textContent = '';
  var kids = path[path.length - 1].kids || [];
  kids.slice(0, 4).forEach(function (k, n) {
    var li = document.createElement('li');
    var b = document.createElement('button');
    b.type = 'button';
    b.className = 'mtn-crumb-collapse-row';
    b.setAttribute('data-kind', k.kids ? 'dir' : 'file');
    b.style.setProperty('--mtn-cc-d', n);
    var g = document.createElement('span');
    g.className = 'mtn-crumb-collapse-glyph';
    g.innerHTML = k.kids ? FOLDER : FILE;
    var nm = document.createElement('span');
    nm.className = 'mtn-crumb-collapse-nm';
    nm.textContent = k.name;
    var sz = document.createElement('span');
    sz.className = 'mtn-crumb-collapse-sz';
    sz.textContent = k.kids ? k.kids.length + ' items' : k.size;
    b.appendChild(g); b.appendChild(nm); b.appendChild(sz);
    if (k.kids) b.addEventListener('click', function () { push(k); });
    else b.setAttribute('aria-disabled', 'true');
    li.appendChild(b);
    list.appendChild(li);
  });
}

function push(node) {
  path.push(node);
  expanded = false;
  drawTrail(true);
  drawList();
}

function pop(i) {
  if (i >= path.length - 1) return;
  var nodes = Array.prototype.slice.call(trail.children);
  var cut = -1, k;
  for (k = 0; k < nodes.length; k++) {
    if (nodes[k].mtnIndex === i) { cut = k; break; }
  }
  var out = cut >= 0 ? nodes.slice(cut + 1) : [];
  out.forEach(function (n) { n.setAttribute('data-anim', 'out'); });
  path = path.slice(0, i + 1);
  expanded = false;
  clearTimeout(timer);
  timer = setTimeout(function () {
    if (!root.isConnected) return;
    drawTrail(false);
    drawList();
  }, out.length ? 190 : 0);
}

up.addEventListener('click', function () { if (path.length > 1) pop(path.length - 2); });

drawTrail(false);
drawList();

