.mtn-radial-wheel{font-family:system-ui,-apple-system,"Segoe UI",sans-serif;background:radial-gradient(90% 80% at 50% 45%,#241338,#0c0714 70%);border:1px solid #34204f;border-radius:16px;padding:8px 10px 10px;color:#e5d9f6;}
.mtn-radial-wheel-stage{position:relative;height:146px;}
