js:
var stage = root.querySelector('.mtn-radial-wheel-stage');
var hub = root.querySelector('.mtn-radial-wheel-hub');
var wedge = root.querySelector('.mtn-radial-wheel-wedge');
var read = root.querySelector('.mtn-radial-wheel-read');
var acts = Array.prototype.slice.call(root.querySelectorAll('.mtn-radial-wheel-act'));
var open = false, hot = -1, flashTimer = 0;

function angleOf(i) { return -90 + i * 60; }

function setHot(i) {
  hot = i;
  acts.forEach(function (a, n) {
    if (n === i) a.setAttribute('data-hot', '1');
    else a.removeAttribute('data-hot');
  });
  if (i >= 0) {
    wedge.style.setProperty('--mtn-rw-ang', (angleOf(i) + 90) + 'deg');
    read.textContent = acts[i].getAttribute('data-name');
  }
}

function setOpen(v) {
  open = v;
  root.setAttribute('data-open', v ? 'true' : 'false');
  hub.setAttribute('aria-expanded', v ? 'true' : 'false');
  hub.setAttribute('aria-label', v ? 'Close create wheel' : 'Open create wheel');
  acts.forEach(function (a) { a.tabIndex = v ? 0 : -1; });
  if (v) { setHot(0); }
  else { setHot(-1); read.textContent = 'Click the hub, then aim'; }
}

function flash(txt) {
  read.textContent = txt;
  read.setAttribute('data-flash', '1');
  clearTimeout(flashTimer);
  flashTimer = setTimeout(function () {
    if (!root.isConnected) return;
    read.removeAttribute('data-flash');
    read.textContent = 'Click the hub, then aim';
  }, 1400);
}

hub.addEventListener('click', function () { setOpen(!open); });

stage.addEventListener('pointermove', function (e) {
  if (!open) return;
  var r = stage.getBoundingClientRect();
  var dx = e.clientX - (r.left + r.width / 2);
  var dy = e.clientY - (r.top + r.height / 2);
  if (Math.abs(dx) + Math.abs(dy) < 18) return;
  var deg = Math.atan2(dy, dx) * 180 / Math.PI;
  var idx = Math.round(((deg + 90) % 360 + 360) % 360 / 60) % 6;
  if (idx !== hot) setHot(idx);
});

acts.forEach(function (a, i) {
  a.addEventListener('focus', function () { if (open) setHot(i); });
  a.addEventListener('click', function () {
    setOpen(false);
    flash(a.getAttribute('data-name') + ' created');
    hub.focus();
  });
});

root.addEventListener('keydown', function (e) {
  if (e.key === 'Escape' && open) { setOpen(false); hub.focus(); return; }
  if (!open) return;
  var n = hot;
  if (e.key === 'ArrowRight' || e.key === 'ArrowDown') n = (hot + 1) % acts.length;
  else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') n = (hot - 1 + acts.length) % acts.length;
  else return;
  e.preventDefault();
  setHot(n);
  acts[n].focus();
});

