js:
var ROUTES = [
  { num: '01 / Journal', h: 'Field notes from a slow week', p: 'Three weeks of type tests, and the widest column still wins.', word: 'Journal' },
  { num: '02 / Work', h: 'Nine projects, two of them public', p: 'Identity, packaging and a booking flow that finally shipped.', word: 'Work' },
  { num: '03 / Studio', h: 'A small room above a bakery', p: 'Two desks, one plotter, and far too many paper samples.', word: 'Studio' }
];

var links = Array.prototype.slice.call(root.querySelectorAll('.mtn-curtain-shutter-link'));
var num = root.querySelector('.mtn-curtain-shutter-num');
var head = root.querySelector('.mtn-curtain-shutter-h');
var para = root.querySelector('.mtn-curtain-shutter-p');
var word = root.querySelector('.mtn-curtain-shutter-word');
var cur = 0, busy = false, t1 = 0, t2 = 0;

function replay(el) {
  el.style.animation = 'none';
  void el.offsetWidth;
  el.style.animation = '';
}

function go(i) {
  if (busy || i === cur) return;
  busy = true;
  word.textContent = ROUTES[i].word;
  root.setAttribute('data-phase', 'cover');
  links.forEach(function (l, n) {
    if (n === i) l.setAttribute('aria-current', 'page');
    else l.removeAttribute('aria-current');
  });
  clearTimeout(t1);
  t1 = setTimeout(function () {
    if (!root.isConnected) return;
    var r = ROUTES[i];
    num.textContent = r.num;
    head.textContent = r.h;
    para.textContent = r.p;
    [num, head, para].forEach(replay);
    cur = i;
    root.setAttribute('data-phase', 'idle');
    clearTimeout(t2);
    t2 = setTimeout(function () {
      if (!root.isConnected) return;
      busy = false;
    }, 560);
  }, 620);
}

links.forEach(function (l, i) {
  l.addEventListener('click', function () { go(i); });
});

