js:
var segs = Array.prototype.slice.call(root.querySelectorAll('.mtn-segment-mask-seg'));
var views = Array.prototype.slice.call(root.querySelectorAll('.mtn-segment-mask-view'));
var thumb = root.querySelector('.mtn-segment-mask-thumb');
var over = root.querySelector('.mtn-segment-mask-over');
var cur = 0;

function clip(i) {
  var step = 100 / segs.length;
  var left = i * step;
  var right = 100 - (i + 1) * step;
  over.style.clipPath = 'inset(0 ' + right.toFixed(3) + '% 0 ' + left.toFixed(3) + '% round 8px)';
}

function select(i, focus) {
  if (i === cur) { if (focus) segs[i].focus(); return; }
  cur = i;
  thumb.style.setProperty('--mtn-sk-i', i);
  clip(i);
  segs.forEach(function (s, n) {
    s.setAttribute('aria-selected', n === i ? 'true' : 'false');
    s.tabIndex = n === i ? 0 : -1;
  });
  views.forEach(function (v, n) {
    if (n === i) v.setAttribute('data-on', '1');
    else v.removeAttribute('data-on');
  });
  if (focus) segs[i].focus();
}

segs.forEach(function (s, i) {
  s.addEventListener('click', function () { select(i, false); });
  s.addEventListener('keydown', function (e) {
    var n = i;
    if (e.key === 'ArrowRight') n = (i + 1) % segs.length;
    else if (e.key === 'ArrowLeft') n = (i - 1 + segs.length) % segs.length;
    else return;
    e.preventDefault();
    select(n, true);
  });
});

thumb.style.setProperty('--mtn-sk-i', 0);
clip(0);

