.mtn-search-capsule[data-open="true"] .mtn-search-capsule-kbd{opacity:1;transition-delay:.2s;}
.mtn-search-capsule-sheet{position:absolute;left:10px;right:10px;top:46px;z-index:4;display:flex;flex-direction:column;gap:3px;padding:5px;border-radius:11px;background:#12161d;border:1px solid #2a323e;box-shadow:0 18px 40px rgba(0,0,0,.6);opacity:0;transform:translateY(-8px);pointer-events:none;transition:opacity .24s ease,transform .34s cubic-bezier(.24,.94,.3,1);}
.mtn-search-capsule[data-open="true"] .mtn-search-capsule-sheet{opacity:1;transform:none;pointer-events:auto;}
.mtn-search-capsule-hit{display:flex;align-items:center;gap:8px;width:100%;padding:5px 6px;appearance:none;background:none;border:0;border-radius:7px;text-align:left;cursor:pointer;color:#c3cbd9;opacity:0;transform:translateY(6px);animation:mtn-search-capsule-drop .3s cubic-bezier(.24,.94,.3,1) both;animation-delay:calc(90ms + var(--mtn-sc-d,0) * 45ms);}
.mtn-search-capsule-hit:hover{background:#1c2531;}
.mtn-search-capsule-hit[data-active="1"]{background:#22304a;}
.mtn-search-capsule-hit:focus-visible{outline:2px solid #7c9cff;outline-offset:-2px;}
.mtn-search-capsule-kind{flex:0 0 auto;padding:2px 4px;border-radius:4px;background:#1e2735;font:700 7.5px/1 ui-monospace,Menlo,monospace;letter-spacing:.1em;text-transform:uppercase;color:#7f92b5;}
.mtn-search-capsule-nm{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font:500 11px/1.3 system-ui,-apple-system,sans-serif;}
.mtn-search-capsule-nm mark{background:none;color:#93b4ff;font-weight:700;}
.mtn-search-capsule-path{font:500 9px/1 ui-monospace,Menlo,monospace;color:#5f6a7e;}
.mtn-search-capsule-none{padding:8px 6px;font:500 10.5px/1 system-ui,-apple-system,sans-serif;color:#6d788c;}
@keyframes mtn-search-capsule-drop{from{opacity:0;transform:translateY(-6px);}to{opacity:1;transform:none;}}
@media (prefers-reduced-motion: reduce){
  .mtn-search-capsule-field{transition-duration:.001ms;}
  .mtn-search-capsule-sheet{transition-duration:.001ms;}
  .mtn-search-capsule-input{transition-duration:.001ms;transition-delay:0ms;}
  .mtn-search-capsule-kbd{transition-duration:.001ms;transition-delay:0ms;}
  .mtn-search-capsule-hit{animation:none;opacity:1;transform:none;}
  .mtn-search-capsule-page{transition-duration:.001ms;}
}

js:
var ITEMS = [
  { k: 'doc', n: 'Brand guidelines', p: 'Design' },
  { k: 'file', n: 'button-states.fig', p: 'Kit' },
  { k: 'person', n: 'Nadia Rahal', p: 'Lead' },
  { k: 'doc', n: 'Motion principles', p: 'Motion' },
  { k: 'file', n: 'tokens.json', p: 'Core' }
];

var btn = root.querySelector('.mtn-search-capsule-btn');
var input = root.querySelector('.mtn-search-capsule-input');
var sheet = root.querySelector('.mtn-search-capsule-sheet');
var scrim = root.querySelector('.mtn-search-capsule-scrim');
var title = root.querySelector('.mtn-search-capsule-title');
var active = 0;
var hits = [];

function mark(text, q) {
  var wrap = document.createElement('span');
  wrap.className = 'mtn-search-capsule-nm';
  var i = q ? text.toLowerCase().indexOf(q.toLowerCase()) : -1;
  if (i < 0) { wrap.textContent = text; return wrap; }
  wrap.appendChild(document.createTextNode(text.slice(0, i)));
  var m = document.createElement('mark');
  m.textContent = text.slice(i, i + q.length);
  wrap.appendChild(m);
  wrap.appendChild(document.createTextNode(text.slice(i + q.length)));
  return wrap;
}

function draw() {
  var q = input.value.trim();
  var list = ITEMS.filter(function (it) {
    return !q || (it.n + ' ' + it.p).toLowerCase().indexOf(q.toLowerCase()) >= 0;
  }).slice(0, 3);
  sheet.textContent = '';
  hits = [];
  if (!list.length) {
    var none = document.createElement('div');
    none.className = 'mtn-search-capsule-none';
    none.textContent = 'No matches for "' + q + '"';
    sheet.appendChild(none);
    return;
  }
  list.forEach(function (it, n) {
    var b = document.createElement('button');
    b.type = 'button';
    b.className = 'mtn-search-capsule-hit';
    b.setAttribute('role', 'option');
    b.style.setProperty('--mtn-sc-d', n);
    var kind = document.createElement('span');
    kind.className = 'mtn-search-capsule-kind';
    kind.textContent = it.k;
    var path = document.createElement('span');
    path.className = 'mtn-search-capsule-path';
    path.textContent = it.p;
    b.appendChild(kind);
    b.appendChild(mark(it.n, q));
    b.appendChild(path);
    b.addEventListener('click', function () { pick(it); });
    b.addEventListener('mouseenter', function () { setActive(n); });
    sheet.appendChild(b);
    hits.push(b);
  });
  setActive(0);
}

function setActive(i) {
  active = i;
  hits.forEach(function (h, n) {
    if (n === i) { h.setAttribute('data-active', '1'); h.setAttribute('aria-selected', 'true'); }
    else { h.removeAttribute('data-active'); h.setAttribute('aria-selected', 'false'); }
  });
}

function pick(it) {
  title.textContent = it.n;
  setOpen(false);
}

function setOpen(v) {
  root.setAttribute('data-open', v ? 'true' : 'false');
  btn.setAttribute('aria-expanded', v ? 'true' : 'false');
  btn.setAttribute('aria-label', v ? 'Close search' : 'Open search');
  input.tabIndex = v ? 0 : -1;
  if (v) { draw(); input.focus(); }
  else { input.value = ''; input.blur(); }
}

btn.addEventListener('click', function () {
  setOpen(root.getAttribute('data-open') !== 'true');
});
scrim.addEventListener('click', function () { setOpen(false); });
input.addEventListener('input', draw);
root.addEventListener('keydown', function (e) {
  if (e.key === 'Escape') { setOpen(false); btn.focus(); return; }
  if (root.getAttribute('data-open') !== 'true' || !hits.length) return;
  if (e.key === 'ArrowDown') { e.preventDefault(); setActive((active + 1) % hits.length); }
  else if (e.key === 'ArrowUp') { e.preventDefault(); setActive((active - 1 + hits.length) % hits.length); }
  else if (e.key === 'Enter') { e.preventDefault(); hits[active].click(); }
});
